css:
@keyframes depth-foil-drift {
  0% {
    background-position: 0 center;
  }

  to {
    background-position: 100%center;
  }
}

.depth-btn,
.depth-label {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.depth-btn {
  justify-content: center;
  height: 44px;
  padding: 0 22px;
  border: 0;
  border-radius: 999px;
  font:
    500 15px/1 ui-sans-serif,
    system-ui,
    -apple-system,
    Segoe UI,
    Roboto,
    sans-serif;
  letter-spacing: 0.01em;
  color: #fff;
  cursor: pointer;
  isolation: isolate;
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
  transition:
    filter 0.2s ease,
    box-shadow 0.2s ease;
}

.depth-label {
  z-index: 2;
}

.depth-btn.depth-icon {
  width: 44px;
  padding: 0;
  border-radius: 14px;
}

.depth-btn.depth-toggle {
  width: 76px;
  padding: 0;
  cursor: pointer;
}

.depth-knob {
  position: absolute;
  z-index: 3;
  top: 7px;
  left: 7px;
  width: 30px;
  height: 30px;
  border-radius: 999px;
  background: radial-gradient(
      120% 120%at 50% 22%,
      rgba(255, 255, 255, var(--knob-hi, 0.55)),
      rgba(255, 255, 255, 0) 55%
    ),
    radial-gradient(
      120% 120%at 50% 100%,
      rgba(0, 0, 0, var(--knob-lo, 0.22)),
      transparent 55%
    ),
    var(--knob, #ffffff);
  box-shadow:
    0 1px 2px rgba(0, 0, 0, 0.35),
    0 2px 5px rgba(0, 0, 0, 0.22),
    inset 0 1px 1px rgba(255, 255, 255, var(--knob-hi, 0.5)),
    inset 0 0 0 1px rgba(0, 0, 0, 0.06);
  transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.depth-toggle[data-on="true"] .depth-knob {
  transform: translateX(32px);
}

.depth-toggle[data-on="false"] {
  filter: saturate(0.6) brightness(0.94);
}

.depth-btn::after,
.depth-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  z-index: 1;
  pointer-events: none;
}

.depth-foil {
  --foil-shift: 0%;
  --glare-x: 50%;
  --glare-y: 50%;
  --pointer-x: 50%;
  --pointer-y: 50%;
  --shine-angle: 135deg;
  color: #14202e;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.5);
  overflow: hidden;
  background: linear-gradient(
    135deg,
    #eee 0,
    #dcdcdc 40%,
    #c9c9c9 72%,
    #e8e8e8 100%
  );
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.5),
    inset 0 1px 1px rgba(255, 255, 255, 0.7),
    inset 0-2px 4px rgba(60, 70, 90, 0.3),
    0 3px 10px rgba(30, 38, 56, 0.3);
}

.depth-foil-l {
  position: absolute;
  inset: -48%;
  z-index: 1;
  background-repeat: no-repeat;
  pointer-events: none;
}

.depth-foil-base {
  background: linear-gradient(
    112deg,
    transparent 22%,
    rgba(0, 220, 255, 0.4) 30%,
    rgba(80, 255, 190, 0.34) 36%,
    rgba(190, 255, 80, 0.26) 41%,
    rgba(255, 230, 70, 0.24) 47%,
    rgba(255, 70, 180, 0.36) 55%,
    rgba(150, 90, 255, 0.36) 63%,
    rgba(60, 120, 255, 0.3) 70%,
    transparent 80%
  );
  background-size: 240% 100%;
  filter: saturate(1.3) contrast(1.25);
  animation: depth-foil-drift 7s ease-in-out infinite alternate;
}

.depth-foil-film {
  background: radial-gradient(
      ellipse at 20% 30%,
      rgba(255, 70, 180, 0.34) 0,
      transparent 48%
    ),
    radial-gradient(
      ellipse at 70% 20%,
      rgba(0, 220, 255, 0.34) 0,
      transparent 52%
    ),
    radial-gradient(
      ellipse at 78% 74%,
      rgba(80, 255, 190, 0.34) 0,
      transparent 56%
    );
  background-size:
    150% 150%,
    160% 160%,
    145% 145%;
  filter: blur(0.4px) saturate(1.4);
  mix-blend-mode: screen;
  opacity: 0.7;
  animation: depth-foil-drift 9s ease-in-out infinite alternate-reverse;
}

@media (prefers-reduced-motion: reduce) {
  .depth-foil-base,
  .depth-foil-film {
    animation: none;
  }
}

.depth-foil-pearl {
  z-index: 2;
  inset: 0;
  background: radial-gradient(
    120% 120%at var(--glare-x, 50%) var(--glare-y, 50%),
    rgba(230, 238, 245, 0.6) 0%,
    rgba(205, 217, 226, 0.2) 26%,
    transparent 58%
  );
  mix-blend-mode: soft-light;
  opacity: 0.95;
  transition: background 0.12s linear;
}

.depth-foil-shine {
  z-index: 4;
  inset: 0;
  background: linear-gradient(
    var(--shine-angle, 120deg),
    transparent 30%,
    rgba(226, 235, 242, 0.5) 48%,
    rgba(0, 124, 255, 0.1) 58%,
    rgba(255, 0, 147, 0.1) 66%,
    transparent 82%
  );
  background-size: 200% 100%;
  background-position: calc(var(--pointer-x, 50%)) center;
  filter: blur(0.25px);
  mix-blend-mode: screen;
  opacity: 0.6;
  transition: background-position 0.12s linear;
}

.depth-foil-glare {
  z-index: 5;
  inset: 0;
  background: radial-gradient(
    circle at var(--glare-x, 50%) var(--glare-y, 50%),
    rgba(230, 238, 245, 0.55) 0%,
    rgba(205, 218, 228, 0.16) 10%,
    transparent 38%
  );
  mix-blend-mode: screen;
  opacity: 0.5;
  transition: background 0.12s linear;
}

@media (prefers-reduced-motion: reduce) {
  .depth-foil-l {
    transition: none;
  }
}
